mkdir -p /tmp/nbhelp /home/analyst/work/figures/analysis && cat > /tmp/nbhelp/run.py <<'EOF'
"""usage: run.py batch.py  -> appends cells from batch file to analysis.ipynb, executes whole notebook.
Batch file: cells separated by lines '# %%' (code) or '# %% [markdown]' (markdown, lines prefixed '# ')."""
import sys, re, nbformat
from nbclient import NotebookClient
nbp='/home/analyst/work/analysis.ipynb'
try: nb=nbformat.read(nbp,as_version=4)
except FileNotFoundError:
    nb=nbformat.v4.new_notebook(); nb.metadata['kernelspec']={'name':'python3','display_name':'Python 3','language':'python'}
if len(sys.argv)>1 and sys.argv[1]!='--rerun':
    src=open(sys.argv[1]).read()
    parts=re.split(r'^# %%(.*)$',src,flags=re.M)
    for hdr,body in zip(parts[1::2],parts[2::2]):
        body=body.strip('\n')
        if 'markdown' in hdr:
            body='\n'.join(l[2:] if l.startswith('# ') else l.lstrip('#') for l in body.split('\n'))
            nb.cells.append(nbformat.v4.new_markdown_cell(body))
        else: nb.cells.append(nbformat.v4.new_code_cell(body))
for c in nb.cells:
    if c.cell_type=='code': c.outputs=[]; c.execution_count=None
NotebookClient(nb,timeout=600,kernel_name='python3',resources={'metadata':{'path':'/home/analyst/work'}}).execute()
nbformat.write(nb,nbp)
print('cells:',len(nb.cells))
EOF
cat > /tmp/nbhelp/show.py <<'EOF'
"""usage: show.py START [END] -> print cells (source tail + text outputs) from index START"""
import sys, nbformat
nb=nbformat.read('/home/analyst/work/analysis.ipynb',as_version=4)
s=int(sys.argv[1]); e=int(sys.argv[2]) if len(sys.argv)>2 else len(nb.cells)
for i,c in enumerate(nb.cells[s:e],s):
    if c.cell_type!='code': continue
    print(f'--- cell {i} ---')
    for o in c.outputs:
        if o.output_type=='stream': print(o.text)
        elif o.output_type in('execute_result','display_data'):
            if 'text/plain' in o.data and 'image/png' not in o.data: print(o.data['text/plain'])
            elif 'image/png' in o.data: print('[image output]')
        elif o.output_type=='error': print('ERROR',o.ename,o.evalue)
EOF
echo ok

python3 -I /tmp/nbhelp/run.py --rerun 2>&1 | grep -v WARNING; python3 -I - <<'EOF'
import nbformat, os
nb=nbformat.read('/home/analyst/work/analysis.ipynb',as_version=4)
errs=warns=0; mixed=0; n_code=0; n_md=0
for i,c in enumerate(nb.cells):
    if c.cell_type=='markdown': n_md+=1; continue
    n_code+=1
    kinds=set()
    for o in c.outputs:
        if o.output_type=='error': errs+=1; print('ERROR in cell',i)
        if o.output_type=='stream':
            kinds.add('text')
            if o.name=='stderr' or 'Warning' in o.text: warns+=1; print('WARN cell',i,o.text[:150])
        if o.output_type in('display_data','execute_result'):
            kinds.add('image' if 'image/png' in o.data else 'text')
    if len(kinds)>1: mixed+=1; print('mixed output types in cell',i)
    if c.execution_count is None: print('not executed:',i)
print(f'code cells {n_code}, markdown cells {n_md}, errors {errs}, warnings {warns}, mixed-output cells {mixed}')
print(os.listdir('figures/analysis'))
EOF
